def fill_basket_shifters(apps, schema_editor):
    """Move current shifter homes and second-basket leads into the basket table."""
    Crews = apps.get_model('timesheets', 'Crews')
    CrewGroup = apps.get_model('timesheets', 'CrewGroup')
    UnitDiscipline = apps.get_model('timesheets', 'UnitDiscipline')
    Discipline = apps.get_model('timesheets', 'Discipline')
    BasketShifter = apps.get_model('timesheets', 'BasketShifter')
    User = apps.get_model('users', 'User')
    BasketLead = apps.get_model('users', 'BasketLead')

    def basket_for(crew_id, discipline_name):
        if crew_id is None or not discipline_name:
            return None
        discipline = Discipline.objects.filter(name=discipline_name).first()
        if discipline is None:
            return None
        crew = Crews.objects.get(pk=crew_id)
        if len(crew.crewname) == 1:
            return UnitDiscipline.objects.filter(crew=crew, discipline=discipline).first()
        group = CrewGroup.objects.filter(groupname=crew.crewname).first()
        return UnitDiscipline.objects.filter(group=group, discipline=discipline).first() if group else None

    def make(basket, shifter, is_home, startdate):
        BasketShifter.objects.create(
            basket=basket, shifter=shifter, is_home=is_home, startdate=startdate,
            basket_key=str(basket.pk), home_key=str(shifter.pk) if is_home else None,
        )

    for user in User.objects.filter(isactive=True):
        basket = basket_for(user.crewid_id, user.shiftertype)
        if basket is not None:
            make(basket, user, True, user.hiredate or timezone.now().date())
    for lead in BasketLead.objects.filter(enddate__isnull=True):
        basket = basket_for(lead.crewid_id, lead.shiftertype)
        if basket is not None and not BasketShifter.objects.filter(basket=basket, enddate__isnull=True).exists():
            make(basket, lead.shifter, False, lead.startdate)


